<script setup lang="ts">import{ref}from'vue';const props=defineProps<{busy:boolean;error:string}>();const emit=defineEmits<{login:[username:string,password:string]}>();const username=ref('admin'),password=ref('');</script>
<template><form class="mx-auto mt-16 max-w-md rounded-2xl border border-cyan-400/20 bg-white/5 p-6" @submit.prevent="emit('login',username,password)"><h2 class="text-xl font-semibold">Dashboard login</h2><p class="mt-2 text-sm text-slate-400">Phiên đăng nhập được bảo vệ bằng HTTPS session cookie.</p><label class="mt-5 grid gap-1 text-sm">Username<input v-model="username" autocomplete="username" class="rounded-lg bg-slate-950 px-3 py-2" required></label><label class="mt-3 grid gap-1 text-sm">Password<input v-model="password" type="password" autocomplete="current-password" class="rounded-lg bg-slate-950 px-3 py-2" required minlength="8"></label><p v-if="props.error" class="mt-3 text-sm text-rose-300">{{props.error}}</p><button class="mt-5 w-full rounded-lg bg-cyan-400 px-4 py-2 font-semibold text-slate-950 disabled:opacity-50" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form></template>
